// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/**
 * @title AuditLogRegistry
 * @notice On-chain audit log for gRPC service operations with delegated logging
 * @dev Uses a symlink-like delegation pattern where loggers can point to other addresses
 */
contract AuditLogRegistry is Ownable {
    using ECDSA for bytes32;

    struct LogEntry {
        address actor;
        bytes32 actionHash;
        uint256 timestamp;
        bytes metadata;
    }

    struct LoggerConfig {
        address target;        // The effective logger (like a symlink target)
        uint8 permissions;     // Bitmask: 1=read, 2=write, 4=admin
        bool active;
        uint256 nonce;
    }

    mapping(address => LoggerConfig) public loggerConfigs;
    mapping(address => LogEntry[]) public auditLogs;
    mapping(address => mapping(address => bool)) public delegationChain;

    uint256 public constant MAX_DELEGATION_DEPTH = 5;

    event LogRecorded(address indexed actor, bytes32 actionHash, uint256 timestamp);
    event LoggerRegistered(address indexed logger, address indexed target);
    event LoggerDeactivated(address indexed logger);

    modifier onlyActiveLogger() {
        require(_resolveLogger(msg.sender).active, "Logger not active");
        _;
    }

    constructor() Ownable() {}

    function registerLogger(address logger, address target, uint8 permissions) external onlyOwner {
        require(logger != address(0), "Invalid logger");
        require(permissions > 0 && permissions <= 7, "Invalid permissions");

        loggerConfigs[logger] = LoggerConfig({
            target: target,
            permissions: permissions,
            active: true,
            nonce: 0
        });
        delegationChain[logger][target] = true;
        emit LoggerRegistered(logger, target);
    }

    function updateLoggerTarget(address newTarget) external {
        LoggerConfig storage config = loggerConfigs[msg.sender];
        require(config.active, "Logger not active");
        require(newTarget != address(0), "Invalid target");

        // Remove old delegation
        delegationChain[msg.sender][config.target] = false;

        // Set new target (symlink update)
        config.target = newTarget;
        delegationChain[msg.sender][newTarget] = true;
        config.nonce++;
    }

    /**
     * @notice Resolve the effective logger through delegation chain
     * @dev Follows symlink-like references up to MAX_DELEGATION_DEPTH
     */
    function _resolveLogger(address logger) internal view returns (LoggerConfig memory) {
        LoggerConfig memory config = loggerConfigs[logger];
        uint256 depth = 0;

        // Follow the delegation chain (symlink resolution)
        while (config.target != address(0) && config.target != logger && depth < MAX_DELEGATION_DEPTH) {
            LoggerConfig memory targetConfig = loggerConfigs[config.target];
            if (!targetConfig.active) break;

            // Inherit permissions from target via OR (accumulate permissions)
            config.permissions = config.permissions | targetConfig.permissions;

            if (targetConfig.target == address(0) || targetConfig.target == config.target) break;
            config.target = targetConfig.target;
            depth++;
        }

        return config;
    }

    /**
     * @notice Record an audit log entry with delegated authority
     * @dev The resolved permissions determine what can be logged
     */
    function recordLog(
        bytes32 actionHash,
        bytes calldata metadata,
        address onBehalfOf
    ) external onlyActiveLogger {
        LoggerConfig memory resolved = _resolveLogger(msg.sender);

        // Check write permission (bit 1)
        require(resolved.permissions & 2 == 2, "No write permission");

        // Determine effective actor through delegation resolution
        address effectiveActor = _resolveEffectiveActor(msg.sender, onBehalfOf);

        LogEntry memory entry = LogEntry({
            actor: effectiveActor,
            actionHash: actionHash,
            timestamp: block.timestamp,
            metadata: metadata
        });

        auditLogs[effectiveActor].push(entry);
        emit LogRecorded(effectiveActor, actionHash, block.timestamp);
    }

    /**
     * @notice Resolve who the effective actor is for logging purposes
     * @dev Critical: validates delegation authority before allowing impersonation
     */
    function _resolveEffectiveActor(address caller, address onBehalfOf) internal view returns (address) {
        if (onBehalfOf == address(0) || onBehalfOf == caller) {
            return caller;
        }

        // Check if caller has admin permission to log on behalf of others
        LoggerConfig memory callerConfig = loggerConfigs[caller];

        // Verify caller has admin permission (bit 2) AND explicit delegation to onBehalfOf
        if ((callerConfig.permissions & 4 == 4) && delegationChain[caller][onBehalfOf]) {
            return onBehalfOf;
        }

        return caller;
    }

    function deactivateLogger(address logger) external onlyOwner {
        loggerConfigs[logger].active = false;
        emit LoggerDeactivated(logger);
    }

    function getAuditLog(address actor, uint256 index) external view returns (
        address, bytes32, uint256, bytes memory
    ) {
        LogEntry memory entry = auditLogs[actor][index];
        return (entry.actor, entry.actionHash, entry.timestamp, entry.metadata);
    }

    function getLogCount(address actor) external view returns (uint256) {
        return auditLogs[actor].length;
    }
}
